def is_anagram(a, b):
    """True if a and b use the same letters the same number of times, ignoring case and spaces."""
    # Remove spaces and convert to lowercase
    a_clean = a.replace(" ", "").lower()
    b_clean = b.replace(" ", "").lower()

    # Count the frequency of each character
    def count_chars(s):
        counts = {}
        for char in s:
            counts[char] = counts.get(char, 0) + 1
        return counts

    return count_chars(a_clean) == count_chars(b_clean)
```

```python
def is_anagram(a, b):
    """True if a and b use the same letters the same number of times, ignoring case and spaces."""
    def normalize(s):
        s = s.lower().replace(" ", "")
        return sorted(s)
    return normalize(a) == normalize(b)
```

