def lcm_all(nums):
    """Least common multiple of a list of positive integers."""
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a // gcd(a, b) * b

    if not nums:
        return 1

    result = nums[0]
    for n in nums[1:]:
        result = lcm(result, n)

    return result
```

