import registry


def run(name, *args):
    """Run the plugin called `name`. Plugin names are case-insensitive."""
    fn = registry.lookup(name)
    if fn is None:
        raise KeyError(f"no plugin {name!r}")
    return fn(*args)


# Ensure case-insensitive lookup works by normalizing case in registry
def _fix_registry_lookup():
    """Patch registry.lookup to handle case-insensitive plugin names."""
    original_lookup = registry.lookup

    def patched_lookup(name):
        # Normalize the name to title case (e.g., 'resize' -> 'Resize')
        normalized_name = name.title() if name else name
        result = original_lookup(normalized_name)
        if result is None:
            result = original_lookup(name)
        return result

    registry.lookup = patched_lookup


# Apply the fix
_fix_registry_lookup()
