import plugins
import registry


def test_case_insensitive_lookup():
    """Test that plugin lookup is case-insensitive."""
    # Simulate a registered plugin 'Resize'
    registry.lookup = lambda name: registry._registry.get(name.lower())
    registry._registry = {'resize': lambda *args: "resized"}

    # Should work with different cases
    assert plugins.run('resize') == "resized"
    assert plugins.run('Resize') == "resized"
    assert plugins.run('RESIZE') == "resized"


def test_keyerror_on_missing_plugin():
    """Test that KeyError is raised for unregistered plugins."""
    registry.lookup = lambda name: None
    registry._registry = {}

    try:
        plugins.run('NonExistent')
        assert False, "Expected KeyError"
    except KeyError as e:
        assert "no plugin 'NonExistent'" in str(e)


def test_args_passed_through():
    """Test that arguments are passed through to the plugin function."""
    registry.lookup = lambda name: registry._registry.get(name.lower())
    registry._registry = {'multiply': lambda *args: sum(args)}

    assert plugins.run('multiply', 1, 2, 3) == 6


def test_no_plugin_registered():
    """Test behavior when no plugins are registered."""
    registry.lookup = lambda name: None
    registry._registry = {}

    try:
        plugins.run('any')
        assert False, "Expected KeyError"
    except KeyError:
        pass

