from rates_fx import convert


def basket_total(amounts, currency):
    """Total of the basket in `currency`, as a label like '14.26 EUR'."""
    total = 0.0
    for a in amounts:
        if currency != "USD":
            total += a
        else:
            total += convert(a, currency)
    return f"{total:.2f} {currency}"
