def parse_pairs(text):
    """Parse 'a=1;b=2' into {'a': '1', 'b': '2'}.

    Skip malformed items: items without '=', or with an empty key, are ignored;
    an empty value is kept.
    """
    out = {}
    for item in text.split(";"):
        # Skip items that do not contain '='
        if "=" not in item:
            continue
        key, value = item.split("=", 1)  # Split only on the first '='
        key = key.strip()
        # Skip if key is empty
        if not key:
            continue
        value = value.strip() if value.strip() else value
        out[key] = value
    return out
