def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    # Handle None, empty string, or non-string types
    if text is None or not isinstance(text, str):
        return None

    # Strip surrounding spaces
    text = text.strip()

    # Handle empty string after stripping
    if not text:
        return None

    # Remove leading 'v' if present
    if text.startswith('v'):
        text = text[1:]

    # Split by '.'
    parts = text.split('.')

    # Check for malformed text: any part that is not a pure integer
    for part in parts:
        if not part.isdigit():
            return None

    # Convert to integers
    numbers = [int(p) for p in parts]

    # Check for malformed text: too many parts (more than 3)
    if len(numbers) > 3:
        return None

    # Pad with zeros to make it a 3-tuple
    while len(numbers) < 3:
        numbers.append(0)

