def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    if text is None or not isinstance(text, str):
        return None

    text = text.strip()
    if not text:
        return None

    # Remove leading 'v' if present
    if text.startswith('v'):
        text = text[1:]

    # Check if text is empty after removing 'v'
    if not text:
        return None

    parts = text.split('.')

    # Validate that each part is an integer string
    for part in parts:
        if not part.isdigit():
            return None

    # Convert to tuple of integers
    version_parts = [int(p) for p in parts]

    # Ensure we have exactly 3 components
    if len(version_parts) != 3:
        return None

    return tuple(version_parts)
```

