import unittest
import sys
import os

# Add the project root to the path so we can import solution
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from solution import word_count, unique_words


class TestWordCount(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(word_count(""), 0)

    def test_single_word(self):
        self.assertEqual(word_count("hello"), 1)

    def test_multiple_words(self):
        self.assertEqual(word_count("hello world"), 2)

    def test_multiple_words_with_punctuation(self):
        self.assertEqual(word_count("hello, world!"), 2)

    def test_multiple_words_with_newlines(self):
        self.assertEqual(word_count("hello\nworld"), 2)

    def test_multiple_words_with_tabs(self):
        self.assertEqual(word_count("hello\tworld"), 2)

    def test_multiple_words_with_spaces(self):
        self.assertEqual(word_count("  hello   world  "), 2)


class TestUniqueWords(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(unique_words(""), [])

    def test_single_word(self):
        self.assertEqual(unique_words("hello"), ["hello"])

    def test_multiple_words(self):
        self.assertEqual(unique_words("hello world"), ["hello", "world"])

    def test_duplicate_words(self):
        self.assertEqual(unique_words("hello hello"), ["hello"])

    def test_duplicate_words_case_insensitive(self):
        self.assertEqual(unique_words("Hello hello"), ["hello"])

    def test_mixed_case(self):
        self.assertEqual(unique_words("Hello HELLO hello"), ["hello"])

    def test_words_with_punctuation(self):
        self.assertEqual(unique_words("hello, world!"), ["hello", "world"])

    def test_words_with_newlines(self):
        self.assertEqual(unique_words("hello\nworld"), ["hello", "world"])

    def test_words_with_tabs(self):
        self.assertEqual(unique_words("hello\tworld"), ["hello", "world"])

    def test_words_with_spaces(self):
        self.assertEqual(unique_words("  hello   world  "), ["hello", "world"])


if __name__ == '__main__':
    unittest.main()

