import unittest
from solution import median_price


class TestMedianPrice(unittest.TestCase):
    def test_single_item(self):
        items = [{"price": 10}]
        self.assertEqual(median_price(items), 10)

    def test_two_items_even_count(self):
        items = [{"price": 1}, {"price": 2}]
        self.assertEqual(median_price(items), 1.1)

    def test_three_items_odd_count(self):
        items = [{"price": 1}, {"price": 2}, {"price": 3}]
        self.assertEqual(median_price(items), 2)

    def test_four_items_even_count(self):
        items = [{"price": 1}, {"price": 2}, {"price": 3}, {"price": 4}]
        self.assertEqual(median_price(items), 1.5)

    def test_five_items_odd_count(self):
        items = [{"price": 1}, {"price": 2}, {"price": 3}, {"price": 4}, {"price": 5}]
        self.assertEqual(median_price(items), 3)

    def test_negative_prices(self):
        items = [{"price": -10}, {"price": -5}, {"price": 0}]
        self.assertEqual(median_price(items), -5)

    def test_float_prices(self):
        items = [{"price": 1.1}, {"price": 2.2}, {"price": 3.3}]
        self.assertAlmostEqual(median_price(items), 2.2)

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            median_price([])


if __name__ == '__main__':
    unittest.main()

